-- AfterHours Circle MVP. Apply with Supabase SQL editor or authorized Management API.
-- No media bucket: uploads remain disabled until a fail-closed processing service exists.
begin;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create table public.profiles(id uuid primary key references auth.users on delete cascade,nickname text not null check(length(nickname) between 1 and 40),adult_attested_at timestamptz not null,created_at timestamptz not null default now());
create table public.leagues(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 80),owner_id uuid not null references public.profiles,allow_history boolean not null default false,created_at timestamptz not null default now());
create table public.league_members(league_id uuid references public.leagues on delete cascade,user_id uuid references public.profiles on delete cascade,nickname text not null,roles text[] not null default array['member'],status text not null default 'active' check(status in('active','left','banned')),joined_at timestamptz not null default now(),primary key(league_id,user_id));
create table public.invite_codes(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,code_hash text not null unique,created_by uuid references public.profiles,expires_at timestamptz,max_uses int check(max_uses>0),uses int not null default 0,requires_approval boolean not null default false,revoked boolean not null default false,created_at timestamptz not null default now());
create table public.join_attempts(id bigint generated always as identity primary key,user_id uuid not null references auth.users on delete cascade,created_at timestamptz not null default now());
create index join_attempts_user_time on public.join_attempts(user_id,created_at);
create table public.join_requests(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,user_id uuid not null references public.profiles on delete cascade,invite_id uuid not null references public.invite_codes on delete cascade,status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz not null default now(),unique(league_id,user_id));
create table public.invite_uses(invite_id uuid references public.invite_codes on delete cascade,user_id uuid references public.profiles on delete cascade,used_at timestamptz not null default now(),primary key(invite_id,user_id));
create table public.channels(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,name text not null check(length(name) between 1 and 40),position int not null default 0,archived boolean not null default false,created_at timestamptz not null default now());
create table public.messages(id uuid primary key default gen_random_uuid(),channel_id uuid not null references public.channels on delete cascade,author_id uuid references public.profiles on delete cascade,body text not null check(length(body) between 1 and 2000),reply_to uuid references public.messages on delete set null,kind text not null default 'text' check(kind in('text','system')),pinned boolean not null default false,created_at timestamptz not null default now(),edited_at timestamptz);
create index messages_channel_time on public.messages(channel_id,created_at);
create table public.reactions(message_id uuid references public.messages on delete cascade,user_id uuid references public.profiles on delete cascade,emoji text not null check(length(emoji) between 1 and 12),primary key(message_id,user_id,emoji));
create table public.reports(id uuid primary key default gen_random_uuid(),league_id uuid not null references public.leagues on delete cascade,message_id uuid references public.messages on delete set null,reporter_id uuid not null references public.profiles on delete cascade,reason text not null check(reason in('nonconsensual','explicit','minor','harassment','other')),status text not null default 'open',created_at timestamptz not null default now());
create table public.blocks(user_id uuid references public.profiles on delete cascade,blocked_id uuid references public.profiles on delete cascade,primary key(user_id,blocked_id),check(user_id<>blocked_id));
-- Future shared game rows are deliberately inaccessible until authoritative writes are implemented.
create table public.rulebooks(id uuid primary key default gen_random_uuid(),league_id uuid references public.leagues on delete cascade,version int not null,snapshot jsonb not null);
create table public.nights(id uuid primary key default gen_random_uuid(),league_id uuid references public.leagues on delete cascade,state text not null check(state in('draft','live','review','finalized')),rule_snapshot jsonb not null,created_at timestamptz not null default now());
create table public.entries(id uuid primary key default gen_random_uuid(),night_id uuid references public.nights on delete cascade,owner_id uuid references public.profiles on delete cascade,category_id text not null,encounter_id uuid not null,visibility text not null default 'private' check(visibility in('private','shared')),scoring_eligible boolean not null default false,sealed boolean not null default true,created_at timestamptz not null default now());
create function public.is_member(l uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from league_members where league_id=l and user_id=auth.uid() and status='active')$$;
create function public.is_admin(l uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from league_members where league_id=l and user_id=auth.uid() and status='active' and roles && array['owner','admin'])$$;
create function public.can_read_message(m uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from messages msg join channels c on c.id=msg.channel_id join league_members lm on lm.league_id=c.league_id and lm.user_id=auth.uid() and lm.status='active' join leagues l on l.id=c.league_id where msg.id=m and (l.allow_history or msg.created_at>=lm.joined_at) and not exists(select 1 from blocks b where b.user_id=auth.uid() and b.blocked_id=msg.author_id))$$;
alter table public.profiles enable row level security;
alter table public.leagues enable row level security;
alter table public.league_members enable row level security;
alter table public.invite_codes enable row level security;
alter table public.join_attempts enable row level security;
alter table public.join_requests enable row level security;
alter table public.invite_uses enable row level security;
alter table public.channels enable row level security;
alter table public.messages enable row level security;
alter table public.reactions enable row level security;
alter table public.reports enable row level security;
alter table public.blocks enable row level security;
alter table public.rulebooks enable row level security;
alter table public.nights enable row level security;
alter table public.entries enable row level security;
create policy profile_self on public.profiles for select to authenticated using(id=auth.uid());
create policy leagues_members on public.leagues for select to authenticated using(is_member(id));
create policy memberships_members on public.league_members for select to authenticated using(is_member(league_id) or user_id=auth.uid());
create policy codes_admin on public.invite_codes for select to authenticated using(is_admin(league_id));
create policy requests_scope on public.join_requests for select to authenticated using(user_id=auth.uid() or is_admin(league_id));
create policy uses_admin on public.invite_uses for select to authenticated using(exists(select 1 from invite_codes i where i.id=invite_id and is_admin(i.league_id)));
create policy channels_members on public.channels for select to authenticated using(is_member(league_id));
create policy messages_members on public.messages for select to authenticated using(exists(select 1 from channels c join league_members lm on lm.league_id=c.league_id and lm.user_id=auth.uid() and lm.status='active' join leagues l on l.id=c.league_id where c.id=messages.channel_id and (l.allow_history or messages.created_at>=lm.joined_at)) and not exists(select 1 from blocks b where b.user_id=auth.uid() and b.blocked_id=messages.author_id));
create policy messages_create on public.messages for insert to authenticated with check(author_id=auth.uid() and kind='text' and not pinned and exists(select 1 from channels c where c.id=channel_id and not c.archived and is_member(c.league_id)));
create policy messages_edit on public.messages for update to authenticated using(author_id=auth.uid() and can_read_message(id)) with check(author_id=auth.uid() and kind='text');
create policy messages_remove on public.messages for delete to authenticated using(can_read_message(id) and (author_id=auth.uid() or exists(select 1 from channels c where c.id=channel_id and is_admin(c.league_id))));
create policy reactions_view on public.reactions for select to authenticated using(can_read_message(message_id));
create policy reactions_create on public.reactions for insert to authenticated with check(user_id=auth.uid() and can_read_message(message_id));
create policy reactions_delete on public.reactions for delete to authenticated using(user_id=auth.uid() and can_read_message(message_id));
create policy reports_create on public.reports for insert to authenticated with check(reporter_id=auth.uid() and is_member(league_id) and exists(select 1 from messages m join channels c on c.id=m.channel_id where m.id=message_id and c.league_id=reports.league_id and can_read_message(m.id)));
create policy reports_view on public.reports for select to authenticated using((reporter_id=auth.uid() and is_member(league_id)) or is_admin(league_id));
create policy blocks_self on public.blocks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
-- Game details remain author-only. No client insert/update grant or policy yet.
create policy entry_author on public.entries for select to authenticated using(owner_id=auth.uid() and exists(select 1 from nights n where n.id=night_id and is_member(n.league_id)));
create policy night_members on public.nights for select to authenticated using(is_member(league_id));
create policy rulebook_members on public.rulebooks for select to authenticated using(is_member(league_id));
-- Explicit privileges rather than relying on project-wide default grants.
revoke all on public.profiles,public.leagues,public.league_members,public.invite_codes,public.join_attempts,public.join_requests,public.invite_uses,public.channels,public.messages,public.reactions,public.reports,public.blocks,public.rulebooks,public.nights,public.entries from anon,authenticated;
grant select on public.profiles,public.leagues,public.league_members,public.invite_codes,public.join_requests,public.invite_uses,public.channels,public.messages,public.reactions,public.reports,public.blocks,public.rulebooks,public.nights,public.entries to authenticated;
grant insert(id,channel_id,author_id,body,reply_to) on public.messages to authenticated;
grant insert(league_id,message_id,reporter_id,reason) on public.reports to authenticated;
grant insert on public.reactions,public.blocks to authenticated;
grant update(body,edited_at) on public.messages to authenticated;
grant delete on public.messages,public.reactions,public.blocks to authenticated;
-- Stop users editing ownership, timestamps, channel/thread IDs or system-card type.
create function public.check_message_reply() returns trigger language plpgsql set search_path=public as $$begin if new.reply_to is not null and not exists(select 1 from messages where id=new.reply_to and channel_id=new.channel_id) then raise exception 'Reply must target a visible message in this channel';end if;return new;end$$;
create trigger message_reply before insert on public.messages for each row execute function public.check_message_reply();
create function public.complete_profile(p_nickname text,p_adult boolean) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null or not p_adult then raise exception 'Adult attestation required';end if;insert into profiles(id,nickname,adult_attested_at) values(auth.uid(),trim(p_nickname),now()) on conflict(id) do update set nickname=excluded.nickname;end$$;
create function public.create_circle(p_name text) returns uuid language plpgsql security definer set search_path=public as $$declare l uuid;nick text;begin select nickname into nick from profiles where id=auth.uid();if nick is null then raise exception 'Complete adult profile first';end if;insert into leagues(name,owner_id) values(trim(p_name),auth.uid()) returning id into l;insert into league_members(league_id,user_id,nickname,roles) values(l,auth.uid(),nick,array['owner','admin','host','member']);insert into channels(league_id,name,position) values(l,'general',0),(l,'tonight',1),(l,'the-debrief',2),(l,'lore',3),(l,'rulebook',4);insert into messages(channel_id,author_id,body,kind) select id,auth.uid(),'Circle opened. Your night, your rules.','system' from channels where league_id=l and name='general';return l;end$$;
create function public.create_invite(p_league uuid,p_hours int default 24,p_max_uses int default 5,p_approval boolean default false,p_rotate boolean default false) returns text language plpgsql security definer set search_path=public,extensions as $$declare code text='';alphabet text='ABCDEFGHJKMNPQRSTUVWXYZ23456789';i int;begin if not is_admin(p_league) then raise exception 'Admin required';end if;if p_hours is not null and p_hours not in(1,24,168) then raise exception 'Invalid expiry';end if;if p_max_uses is not null and p_max_uses not in(1,5,10) then raise exception 'Invalid use limit';end if;if p_rotate then update invite_codes set revoked=true where league_id=p_league;end if;for i in 1..8 loop code=code||substr(alphabet,(get_byte(gen_random_bytes(1),0)%length(alphabet))+1,1);end loop;insert into invite_codes(league_id,code_hash,created_by,expires_at,max_uses,requires_approval) values(p_league,encode(digest(code,'sha256'),'hex'),auth.uid(),case when p_hours is null then null else now()+make_interval(hours=>p_hours) end,p_max_uses,p_approval);return substr(code,1,4)||'-'||substr(code,5,4);end$$;
create function public.revoke_invite(p_id uuid) returns void language plpgsql security definer set search_path=public as $$begin update invite_codes set revoked=true where id=p_id and is_admin(league_id);end$$;
create function public.join_circle(p_code text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare inv invite_codes;nick text;begin if auth.uid() is null then return jsonb_build_object('error','Sign in first');end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));if (select count(*) from join_attempts where user_id=auth.uid() and created_at>now()-interval '1 hour')>=10 then return jsonb_build_object('error','Too many attempts. Try again in an hour.');end if;insert into join_attempts(user_id) values(auth.uid());select nickname into nick from profiles where id=auth.uid();if nick is null then return jsonb_build_object('error','Complete adult profile first');end if;select * into inv from invite_codes where code_hash=encode(digest(upper(replace(trim(p_code),'-','')),'sha256'),'hex') for update;if inv.id is null or inv.revoked or (inv.expires_at is not null and inv.expires_at<=now()) or (inv.max_uses is not null and inv.uses>=inv.max_uses) then return jsonb_build_object('error','Invalid or expired invitation');end if;if exists(select 1 from league_members where league_id=inv.league_id and user_id=auth.uid() and status='banned') then return jsonb_build_object('error','Cannot join this circle');end if;if is_member(inv.league_id) then return jsonb_build_object('league_id',inv.league_id);end if;if exists(select 1 from join_requests where league_id=inv.league_id and user_id=auth.uid() and status='pending') then return jsonb_build_object('pending',true);end if;if inv.requires_approval then insert into join_requests(league_id,user_id,invite_id) values(inv.league_id,auth.uid(),inv.id) on conflict(league_id,user_id) do update set invite_id=excluded.invite_id,status='pending',created_at=now();else insert into league_members(league_id,user_id,nickname) values(inv.league_id,auth.uid(),nick) on conflict(league_id,user_id) do update set status='active',roles=array['member'],nickname=excluded.nickname,joined_at=now();end if;update invite_codes set uses=uses+1 where id=inv.id;insert into invite_uses(invite_id,user_id) values(inv.id,auth.uid()) on conflict do nothing;return jsonb_build_object('league_id',inv.league_id,'pending',inv.requires_approval);end$$;
create function public.approve_join(p_request uuid,p_approve boolean) returns void language plpgsql security definer set search_path=public as $$declare req join_requests;inv invite_codes;begin select * into req from join_requests where id=p_request for update;if req.id is null or not is_admin(req.league_id) or req.status<>'pending' then raise exception 'Pending request and admin required';end if;select * into inv from invite_codes where id=req.invite_id;if p_approve and (inv.revoked or (inv.expires_at is not null and inv.expires_at<=now())) then raise exception 'Invitation revoked or expired';end if;if exists(select 1 from league_members where league_id=req.league_id and user_id=req.user_id and status='banned') then raise exception 'Member banned';end if;if p_approve then insert into league_members(league_id,user_id,nickname) select req.league_id,req.user_id,nickname from profiles where id=req.user_id on conflict(league_id,user_id) do update set status='active',roles=array['member'],joined_at=now();end if;update join_requests set status=case when p_approve then 'approved' else 'rejected' end where id=p_request;end$$;
create function public.manage_channel(p_league uuid,p_name text,p_id uuid default null,p_archived boolean default false,p_position int default 0) returns void language plpgsql security definer set search_path=public as $$begin if not is_admin(p_league) then raise exception 'Admin required';end if;if p_id is null then insert into channels(league_id,name,position) values(p_league,trim(p_name),p_position);else update channels set name=trim(p_name),archived=p_archived,position=p_position where id=p_id and league_id=p_league;end if;end$$;
create function public.pin_message(p_message uuid,p_pin boolean) returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from messages m join channels c on c.id=m.channel_id where m.id=p_message and is_admin(c.league_id) and can_read_message(m.id)) then raise exception 'Admin required';end if;update messages set pinned=p_pin where id=p_message;end$$;
create function public.remove_member(p_league uuid,p_user uuid) returns void language plpgsql security definer set search_path=public as $$begin if not is_admin(p_league) or exists(select 1 from leagues where id=p_league and owner_id=p_user) then raise exception 'Cannot remove this member';end if;update league_members set status='banned' where league_id=p_league and user_id=p_user;update invite_codes set revoked=true where league_id=p_league and created_by=p_user;update join_requests set status='rejected' where league_id=p_league and user_id=p_user;delete from messages where author_id=p_user and channel_id in(select id from channels where league_id=p_league);delete from entries where owner_id=p_user and night_id in(select id from nights where league_id=p_league);end$$;
create function public.leave_circle(p_league uuid) returns void language plpgsql security definer set search_path=public as $$begin if exists(select 1 from leagues where id=p_league and owner_id=auth.uid()) then raise exception 'Owner must delete or transfer the circle first';end if;delete from messages where author_id=auth.uid() and channel_id in(select id from channels where league_id=p_league);delete from entries where owner_id=auth.uid() and night_id in(select id from nights where league_id=p_league);update league_members set status='left' where league_id=p_league and user_id=auth.uid();end$$;
create function public.delete_circle(p_league uuid) returns void language plpgsql security definer set search_path=public as $$begin delete from leagues where id=p_league and owner_id=auth.uid();end$$;
create function public.delete_my_account() returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception 'Sign in required';end if;delete from leagues where owner_id=auth.uid();update invite_codes set created_by=null where created_by=auth.uid();delete from auth.users where id=auth.uid();end$$;
create function public.circle_status() returns int language sql immutable as $$select 1$$;
revoke execute on function public.circle_status() from public;
grant execute on function public.circle_status() to anon,authenticated;
-- The version probe exposes no data. All other RPC/table access requires authentication.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('is_member','is_admin','can_read_message','check_message_reply','complete_profile','create_circle','create_invite','revoke_invite','join_circle','approve_join','manage_channel','pin_message','remove_member','leave_circle','delete_circle','delete_my_account') loop execute format('revoke execute on function %s from public,anon',f.signature);end loop;end$$;
grant execute on function public.is_member(uuid),public.is_admin(uuid),public.can_read_message(uuid),public.complete_profile(text,boolean),public.create_circle(text),public.create_invite(uuid,int,int,boolean,boolean),public.revoke_invite(uuid),public.join_circle(text),public.approve_join(uuid,boolean),public.manage_channel(uuid,text,uuid,boolean,int),public.pin_message(uuid,boolean),public.remove_member(uuid,uuid),public.leave_circle(uuid),public.delete_circle(uuid),public.delete_my_account() to authenticated;
-- Broadcast only triggers refetch; the client never trusts event row payloads.
do $$begin if exists(select 1 from pg_publication where pubname='supabase_realtime') then alter publication supabase_realtime add table public.messages,public.reactions,public.channels;end if;end$$;
commit;
